                    public RecordItemWithoutKey<string> RecordStructMember { get; init; }
                }
            }
            """;

        await AssertGeneratorAndAnalyzerSucceedAsync(libSource, appSource);
    }

    [Fact]
    public async Task ClosedGenericStructFromReferencedAssembly_BothStringAndIntKeyNull_DoesNotThrow()
    {
        string libSource = """
            using MessagePack;

            namespace Lib
            {
                [MessagePackObject]
                public partial struct ItemWithNullKey<T>
                {
                    [Key((string)null)]
                    public T Value { get; set; }
                }

                [MessagePackObject]
                public partial record struct RecordItemWithNullKey<T>
                {
                    [Key((string)null)]
                    public T Value { get; set; }
                }
            }
            """;

        string appSource = """
            using MessagePack;
            using Lib;

            namespace App
            {
                [MessagePackObject]
                public sealed partial record Cmd([property: Key(0)] string Scope)
                {
                    [Key(1)]
                    public ItemWithNullKey<int> StructMember { get; init; }

                    [Key(2)]
                    public RecordItemWithNullKey<string> RecordStructMember { get; init; }
                }
            }
            """;

        await AssertGeneratorAndAnalyzerSucceedAsync(libSource, appSource);
    }

    private static async Task AssertGeneratorAndAnalyzerSucceedAsync(string libSource, string appSource)
    {
        ImmutableArray<MetadataReference> netReferences = await ReferenceAssemblies.Net.Net80.ResolveAsync(LanguageNames.CSharp, CancellationToken.None);
        ImmutableArray<MetadataReference> baseReferences = netReferences.AddRange(ReferencesHelper.GetReferences(ReferencesSet.MessagePack));

        var parseOptions = new CSharpParseOptions(LanguageVersion.Latest);

        CSharpCompilation libCompilation = CSharpCompilation.Create(
            "Lib",
            new[] { CSharpSyntaxTree.ParseText(libSource, parseOptions) },
            baseReferences,
            new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));

        using var libStream = new MemoryStream();
        var emitResult = libCompilation.Emit(libStream);
        Assert.True(emitResult.Success, string.Join(Environment.NewLine, emitResult.Diagnostics));

        MetadataReference libReference = MetadataReference.CreateFromImage(libStream.ToArray());

        CSharpCompilation appCompilation = CSharpCompilation.Create(
            "App",
            new[] { CSharpSyntaxTree.ParseText(appSource, parseOptions) },
            baseReferences.Add(libReference),
            new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));

        GeneratorDriver driver = CSharpGeneratorDriver.Create(new MessagePackGenerator().AsSourceGenerator());
        driver = driver.RunGeneratorsAndUpdateCompilation(appCompilation, out Compilation outputCompilation, out ImmutableArray<Diagnostic> generatorDiagnostics);
        GeneratorDriverRunResult runResult = driver.GetRunResult();

        Assert.DoesNotContain(generatorDiagnostics, d => d.Id == "CS8785");
        Assert.DoesNotContain(runResult.Diagnostics, d => d.Id == "CS8785");
        Assert.All(runResult.Results, r => Assert.Null(r.Exception));

        var generatedSources = runResult.Results.SelectMany(r => r.GeneratedSources).ToList();
        Assert.NotEmpty(generatedSources);
        Assert.Contains(generatedSources, s => s.SourceText.ToString().Contains("GeneratedMessagePackResolver", StringComparison.Ordinal));
        Assert.DoesNotContain(outputCompilation.GetDiagnostics(), d => d.Severity == DiagnosticSeverity.Error);

        ImmutableArray<Diagnostic> analyzerDiagnostics = await appCompilation
            .WithAnalyzers(ImmutableArray.Create<DiagnosticAnalyzer>(new MsgPack00xMessagePackAnalyzer()))
            .GetAnalyzerDiagnosticsAsync();

        Assert.DoesNotContain(analyzerDiagnostics, d => d.Id == "AD0001");
        Assert.All(analyzerDiagnostics, d => Assert.True(d.Location.IsInSource, $"Unexpected non-source diagnostic: {d}"));
    }
}

