using Microsoft.CodeAnalysis.Emit;
using Microsoft.CodeAnalysis.Testing;

public class Ledger_2283_Objection2
{
    [Fact]
    public async Task MetadataPropertyWithoutKey_DoesNotThrowOrReportInvalidLocation()
    {
        string libSource = """
            #nullable enable
            using MessagePack;

            namespace Lib;

            [MessagePackObject]
            public partial struct ItemNoKey<T>
            {
                public T Value { get; set; }
            }

            public class BaseWithMetadataProperty
            {
                public string InheritedNoKey { get; set; } = string.Empty;
            }
            """;

        string appSource = """
            #nullable enable
            using MessagePack;
            using Lib;

            namespace App;

            [MessagePackObject]
            public sealed partial class Holder
            {
                [Key(0)]
                public ItemNoKey<int> Member { get; set; }
            }

            [MessagePackObject]
            public sealed partial class DerivedHolder : BaseWithMetadataProperty
            {
                [Key(0)]
                public int OwnKey { get; set; }
            }
            """;

        (ImmutableArray<MetadataReference> baseReferences, MetadataReference libReference) = await CompileLibraryAsync(libSource);

        CSharpCompilation appCompilation = CSharpCompilation.Create(
            "App",
            new[] { CSharpSyntaxTree.ParseText(appSource, new CSharpParseOptions(LanguageVersion.Latest)) },
            baseReferences.Add(libReference),
            new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));

        GeneratorDriver driver = CSharpGeneratorDriver.Create(new MessagePackGenerator().AsSourceGenerator());
        driver = driver.RunGeneratorsAndUpdateCompilation(appCompilation, out _, out ImmutableArray<Diagnostic> generatorDiagnostics);
        GeneratorDriverRunResult runResult = driver.GetRunResult();

        Assert.Empty(generatorDiagnostics);
        Assert.Empty(runResult.Diagnostics);
        Assert.All(runResult.Results, r => Assert.Null(r.Exception));
        Assert.NotEmpty(runResult.Results.SelectMany(r => r.GeneratedSources));

        ImmutableArray<Diagnostic> analyzerDiagnostics = await appCompilation
            .WithAnalyzers(ImmutableArray.Create<DiagnosticAnalyzer>(new MsgPack00xMessagePackAnalyzer()))
            .GetAnalyzerDiagnosticsAsync();

        Assert.DoesNotContain(analyzerDiagnostics, d => d.Id == "AD0001");
        Assert.All(analyzerDiagnostics, d =>
        {
            Assert.True(d.Location.IsInSource);
            Assert.NotNull(d.Location.SourceTree);
            Assert.True(appCompilation.ContainsSyntaxTree(d.Location.SourceTree!));
        });
        Assert.Empty(analyzerDiagnostics);
    }

