using System;
using System.IO;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using MessagePack.SourceGenerator;
using MessagePack.SourceGenerator.Analyzers;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.Diagnostics;
using Microsoft.CodeAnalysis.Emit;
using Microsoft.CodeAnalysis.Testing;

public class Ledger_2283_Objection3
{
    private const string LibSource = """
using MessagePack;

namespace Lib;

[MessagePackObject]
public partial struct Item<T>
{
    [Key(0)]
    public T Value { get; set; }

    [Key((string)null)]
    public string InvalidKey { get; set; }
}

[MessagePackObject]
public partial class RefItem<T>
{
    [Key(0)]
    public T Value { get; set; }

    [Key((string)null)]
    public string InvalidKey { get; set; }
}
""";

    [Fact]
    public async Task ClosedGenericCollectionWrappingMetadataGenericStructAndPrimitive_DoesNotCrashGeneratorOrAnalyzer()
    {
        string appSource = """
using System.Collections.Generic;
using MessagePack;
using Lib;

namespace App;

[MessagePackObject]
public sealed partial record Cmd([property: Key(0)] string Scope)
{
    [Key(1)]
    public List<Item<int>> StructList { get; init; } = new();

    [Key(2)]
    public List<int> IntList { get; init; } = new();
}
""";

        await VerifyAppCompilationAsync(appSource);
    }

    [Fact]
    public async Task ClosedGenericReferenceTypeFromReferencedAssembly_DoesNotCrashGeneratorOrAnalyzer()
    {
        string appSource = """
using System.Collections.Generic;
using MessagePack;
using Lib;

namespace App;

[MessagePackObject]
public sealed partial record Cmd([property: Key(0)] string Scope)
{
    [Key(1)]
    public RefItem<int> RefMember { get; init; } = new();

    [Key(2)]
    public List<RefItem<int>> RefList { get; init; } = new();
}
""";

        await VerifyAppCompilationAsync(appSource);
    }

    private static async Task VerifyAppCompilationAsync(string appSource)
    {
        ImmutableArray<MetadataReference> frameworkRefs = await ReferenceAssemblies.Net.Net80.ResolveAsync(LanguageNames.CSharp, CancellationToken.None);
        MetadataReference[] baseRefs = frameworkRefs.Concat(ReferencesHelper.GetReferences(ReferencesSet.MessagePack)).ToArray();

        CSharpCompilation libCompilation = CSharpCompilation.Create(
            "Lib",
            new[] { CSharpSyntaxTree.ParseText(LibSource, new CSharpParseOptions(LanguageVersion.Latest)) },
            baseRefs,
            new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));

        using MemoryStream libStream = new();
        EmitResult emitResult = libCompilation.Emit(libStream);
        Assert.True(emitResult.Success, string.Join(Environment.NewLine, emitResult.Diagnostics));

        MetadataReference libRef = MetadataReference.CreateFromImage(libStream.ToArray());
        MetadataReference[] appRefs = baseRefs.Append(libRef).ToArray();

        CSharpCompilation appCompilation = CSharpCompilation.Create(
            "App",
            new[] { CSharpSyntaxTree.ParseText(appSource, new CSharpParseOptions(LanguageVersion.Latest)) },
            appRefs,
            new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));

        GeneratorDriver driver = CSharpGeneratorDriver.Create(new MessagePackGenerator().AsSourceGenerator());
        driver = driver.RunGeneratorsAndUpdateCompilation(appCompilation, out Compilation outputCompilation, out ImmutableArray<Diagnostic> generatorDiagnostics);
        GeneratorDriverRunResult runResult = driver.GetRunResult();

        Assert.DoesNotContain(generatorDiagnostics, d => d.Id == "CS8785" || d.Severity >= DiagnosticSeverity.Warning);
        Assert.DoesNotContain(runResult.Diagnostics, d => d.Id == "CS8785" || d.Severity >= DiagnosticSeverity.Warning);
        Assert.All(runResult.Results, r => Assert.Null(r.Exception));
        Assert.Contains(
            runResult.Results.SelectMany(r => r.GeneratedSources),
            s => s.HintName.Contains("GeneratedMessagePackResolver", StringComparison.Ordinal));
        Assert.DoesNotContain(outputCompilation.GetDiagnostics(), d => d.Severity == DiagnosticSeverity.Error);

        ImmutableArray<Diagnostic> analyzerDiagnostics = await appCompilation
            .WithAnalyzers(ImmutableArray.Create<DiagnosticAnalyzer>(new MsgPack00xMessagePackAnalyzer()))
            .GetAnalyzerDiagnosticsAsync();

        Assert.DoesNotContain(analyzerDiagnostics, d => d.Id == "AD0001");
        Assert.Empty(analyzerDiagnostics);
    }
}

